{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 2 * 10^5",
      "description": "The number of vertices in the graph is between 1 and 200,000, inclusive."
    },
    {
      "id": "P2",
      "expression": "1 <= m <= 3 * 10^5",
      "description": "The number of edges in the graph is between 1 and 300,000, inclusive."
    },
    {
      "id": "P3",
      "expression": "1 <= q <= 5 * 10^5",
      "description": "The number of queries is between 1 and 500,000, inclusive."
    },
    {
      "id": "P4",
      "expression": "1 <= p_i <= n",
      "description": "Each vertex has a distinct integer value between 1 and n, inclusive."
    },
    {
      "id": "P5",
      "expression": "1 <= a_i, b_i <= n",
      "description": "Each edge connects two distinct vertices within the graph."
    },
    {
      "id": "P6",
      "expression": "1 <= v <= n",
      "description": "Each query of the first type targets a valid vertex."
    },
    {
      "id": "P7",
      "expression": "1 <= i <= m",
      "description": "Each query of the second type targets a valid edge."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output_value == p_u",
      "description": "For each query of the first type, the output is the value of p_u on the chosen vertex u."
    },
    {
      "id": "Q2",
      "expression": "output_value == 0",
      "description": "For each query of the first type when no vertex has a positive value, the output is 0."
    }
  ],
  "invariants": []
}
